"use client";

import * as React from "react";

/**
 * Brand marks the bundled @lobehub/icons set lacks, drawn from the brands' own vector
 * logos: Simple Icons (CC0) paths with their official hex, or the vendor's site when
 * Simple Icons has none. Each brand exposes the same pair as a lobehub icon: a flat
 * ``Mark`` for menu rows and a round ``Avatar`` for cards, both taking ``size``.
 */

/** Size contract shared with the lobehub marks. */
export interface BrandMarkProps {
  size: number;
}

/** A brand's flat mark and round avatar. */
export interface Brand {
  Mark: React.ComponentType<BrandMarkProps>;
  Avatar: React.ComponentType<BrandMarkProps>;
}

// Pale brand colours need a dark glyph on their disc; the rest take white.
const LUMINANCE_THRESHOLD = 0.4;
// Share of the disc the glyph fills; Simple Icons paths run edge to edge, so this sits
// a little under lobehub's 0.7-0.75 to keep the corners inside the circle.
const AVATAR_ICON_MULTIPLE = 0.62;

/** WCAG relative luminance of a ``#rrggbb`` colour. */
function luminance(hex: string): number {
  const channel = (offset: number) => {
    const c = parseInt(hex.slice(offset, offset + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * channel(1) + 0.7152 * channel(3) + 0.0722 * channel(5);
}

/** Build a brand's Mark/Avatar pair from one single-colour vector path. */
function brand({
  title,
  hex,
  viewBox,
  path,
}: {
  title: string;
  hex: string;
  viewBox: string;
  path: string;
}): Brand {
  // A black brand colour would vanish on the dark theme, so the flat mark follows the text colour.
  const markColor = hex === "#000000" ? "currentColor" : hex;
  const glyphColor = luminance(hex) < LUMINANCE_THRESHOLD ? "#fff" : "#000";
  const Glyph = ({ size, color }: { size: number; color: string }) => (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      fill={color}
      role="img"
      aria-label={title}
      style={{ flex: "none", lineHeight: 1 }}
    >
      <path d={path} />
    </svg>
  );
  const Mark = ({ size }: BrandMarkProps) => <Glyph size={size} color={markColor} />;
  const Avatar = ({ size }: BrandMarkProps) => (
    <span
      dir="ltr"
      className={
        hex === "#000000"
          ? "inline-flex shrink-0 items-center justify-center rounded-full dark:shadow-[inset_0_0_0_1px_rgba(255,255,255,0.1)]"
          : "inline-flex shrink-0 items-center justify-center rounded-full"
      }
      style={{ width: size, height: size, background: hex }}
    >
      <Glyph size={Math.round(size * AVATAR_ICON_MULTIPLE)} color={glyphColor} />
    </span>
  );
  Mark.displayName = `${title}.Mark`;
  Avatar.displayName = `${title}.Avatar`;
  return { Mark, Avatar };
}

