/**
 * Build a brand's Mark/Avatar pair from a full-colour logo the single-colour ``brand``
 * builder cannot draw: the logo itself as the mark, and on a white disc as the avatar.
 */
function colorBrand({
  title,
  viewBox,
  paths,
}: {
  title: string;
  viewBox: string;
  paths: ReadonlyArray<readonly [d: string, fill: string]>;
}): Brand {
  const Mark = ({ size }: BrandMarkProps) => (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      role="img"
      aria-label={title}
      style={{ flex: "none", lineHeight: 1 }}
    >
      {paths.map(([d, fill]) => (
        <path key={d} d={d} fill={fill} />
      ))}
    </svg>
  );
  const Avatar = ({ size }: BrandMarkProps) => (
    <span
      dir="ltr"
      className="inline-flex shrink-0 items-center justify-center rounded-full bg-white shadow-[inset_0_0_0_1px_rgba(0,0,0,0.08)]"
      style={{ width: size, height: size }}
    >
      <Mark size={Math.round(size * AVATAR_ICON_MULTIPLE)} />
    </span>
  );
  Mark.displayName = `${title}.Mark`;
  Avatar.displayName = `${title}.Avatar`;
  return { Mark, Avatar };
}

